"""Generate the published schema reference from the dashboard's declarations."""
from pathlib import Path
import argparse
import sys

ROOT = Path(__file__).resolve().parents[1]
sys.path.insert(0, str(ROOT))
from app.schema_manifest import MAPPING_MANIFESTO, SOURCE_SCHEMAS, TARGET_SCHEMAS


def render():
    lines = ["# FireTrace schema mapping", "",
             "Generated by `python scripts/build_schema_docs.py`; do not edit the tables manually.", "",
             "These are three FIRMS-shaped source groups and four logical JSON evidence views,",
             "not a database or an external validation claim. Full methods and primary product",
             "references are in [SCIENCE.md](SCIENCE.md); input limits are in [INPUTS.md](INPUTS.md).", ""]
    for name, schema in SOURCE_SCHEMAS.items():
        lines.extend([f"## {name}", "", schema["description"], "", "| Field | Meaning |", "| --- | --- |"])
        lines.extend(f"| `{key}` | {value.replace('|', '/')} |" for key, value in schema["fields"].items())
        lines.append("")
    for name, schema in TARGET_SCHEMAS.items():
        mapping = next(item for item in MAPPING_MANIFESTO if item["target_table"] == name)
        lines.extend([f"## {name}", "", mapping["anchor_source"], ""])
        lines.extend(f"- {step}" for step in mapping["join_paths"])
        lines.extend(["", "| Field | Meaning |", "| --- | --- |"])
        lines.extend(f"| `{key}` | {value.replace('|', '/')} |" for key, value in schema.items())
        lines.append("")
    return "\n".join(lines)


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--check", action="store_true")
    args = parser.parse_args()
    target = ROOT / "docs/MAPPING_MANIFESTO.md"
    content = render()
    if args.check:
        valid = target.exists() and target.read_text(encoding="utf-8") == content
        print("Schema documentation current" if valid else "Schema documentation stale; regenerate it")
        return 0 if valid else 1
    target.write_text(content, encoding="utf-8")
    print("Generated docs/MAPPING_MANIFESTO.md")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
